package com.nextstep.service;
import com.nextstep.entity.*;
import com.nextstep.repository.*;
import com.nextstep.web.Errors;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.domain.Specification;
import java.time.*;
import java.util.*;
@Service public class QuizService {
 final QuestionRepository questions;final QuizAttemptRepository attempts;final JsonService json;
 public QuizService(QuestionRepository questions,QuizAttemptRepository attempts,JsonService json){this.questions=questions;this.attempts=attempts;this.json=json;}
 public Specification<Question> filter(String kind,String topic,String difficulty,String search){return (r,q,b)->{var predicates=new ArrayList<jakarta.persistence.criteria.Predicate>();predicates.add(b.equal(r.get("kind"),kind));if(topic!=null&&!topic.isBlank())predicates.add(b.equal(r.get("topic"),topic));if(difficulty!=null&&!difficulty.isBlank())predicates.add(b.equal(r.get("difficulty"),difficulty));if(search!=null&&!search.isBlank())predicates.add(b.like(b.lower(r.get("prompt")),"%"+search.toLowerCase(Locale.ROOT)+"%"));return b.and(predicates.toArray(jakarta.persistence.criteria.Predicate[]::new));};}
 public Map<String,Object> question(Question q,boolean review){var m=new LinkedHashMap<String,Object>();m.put("id",q.id);m.put("topic",q.topic);m.put("difficulty",q.difficulty);m.put("prompt",q.prompt);m.put("options",json.read(q.options));if(review){m.put("answer",q.answer);m.put("explanation",q.explanation);}return m;}
 public Map<String,Object> browse(String kind,String topic,String difficulty,String search,int page){var result=questions.findAll(filter(kind,topic,difficulty,search),PageRequest.of(Math.max(0,page),20,Sort.by("id")));return Map.of("items",result.stream().map(q->question(q,true)).toList(),"total",result.getTotalElements(),"pages",result.getTotalPages());}
 @Transactional public Map<String,Object> start(long uid,String kind,String topic,String difficulty,int count,int duration){if(!List.of("aptitude","technical").contains(kind))throw Errors.bad("Invalid practice module.");var pool=new ArrayList<>(questions.findAll(filter(kind,topic,difficulty,null),PageRequest.of(0,500,Sort.by("id"))).getContent());if(pool.isEmpty())throw Errors.bad("No questions match those filters.");Collections.shuffle(pool);var chosen=pool.subList(0,Math.min(count,pool.size()));var a=new QuizAttempt();a.userId=uid;a.kind=kind;a.status="IN_PROGRESS";a.questionIds=json.write(chosen.stream().map(q->q.id).toList());a.answers="{}";a.score=0;a.total=chosen.size();a.durationSeconds=duration;a.elapsedSeconds=0;a.details="[]";attempts.save(a);return Map.of("id",a.id,"questions",chosen.stream().map(q->question(q,false)).toList(),"durationSeconds",duration,"startedAt",a.createdAt);}
 @Transactional public QuizAttempt finish(long uid,long id,Map<String,Integer> answers){var a=attempts.findById(id).filter(x->x.userId==uid).orElseThrow(()->Errors.bad("Attempt not found."));if(!a.status.equals("IN_PROGRESS"))throw Errors.bad("This attempt was already submitted.");var ids=new ArrayList<Long>();json.read(a.questionIds).forEach(n->ids.add(n.asLong()));if(answers.size()>ids.size()||answers.entrySet().stream().anyMatch(e->!ids.contains(parseId(e.getKey()))||e.getValue()==null||e.getValue()<0||e.getValue()>3))throw Errors.bad("Invalid answers.");var elapsed=(int)Math.min(Integer.MAX_VALUE,Duration.between(a.createdAt,Instant.now()).getSeconds());boolean expired=a.durationSeconds>0&&elapsed>a.durationSeconds+30;var review=new ArrayList<Map<String,Object>>();int score=0;for(long qid:ids){var q=questions.findById(qid).orElseThrow();Integer selected=expired?null:answers.get(Long.toString(qid));boolean correct=Objects.equals(q.answer,selected);if(correct)score++;var item=question(q,true);item.put("selected",selected);item.put("correct",correct);review.add(item);}a.score=score;a.elapsedSeconds=elapsed;a.status=expired?"EXPIRED":"COMPLETED";a.answers=json.write(answers);a.details=json.write(review);return attempts.save(a);}
 private long parseId(String s){try{return Long.parseLong(s);}catch(Exception e){return -1;}}
}
